{"answer":"Implements all contract validations, raises ValueError on rejection, and returns file and byte totals without mutating inputs.","code":"import hashlib


def verify_snapshot(entries, blobs, per_file_limit, total_limit):
    if per_file_limit < 0 or total_limit < 0:
        raise ValueError('Negative limit')

    seen = set()
    total_bytes = 0
    for entry in entries:
        path = entry['path']
        size = entry['size']
        digest = entry['sha256']

        if size < 0:
            raise ValueError('Negative declared size')
        if not path or '\\' in path or '\x00' in path:
            raise ValueError('Invalid path')
        if any(part in ('', '.', '..') for part in path.split('/')):
            raise ValueError('Invalid path')
        if path in seen:
            raise ValueError('Repeated path')
        seen.add(path)

        if path not in blobs:
            raise ValueError('Missing blob')
        data = blobs[path]
        actual_size = len(data)
        if actual_size != size:
            raise ValueError('Size mismatch')
        if actual_size > per_file_limit:
            raise ValueError('Per-file limit exceeded')
        total_bytes += actual_size
        if total_bytes > total_limit:
            raise ValueError('Total limit exceeded')

        if len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
            raise ValueError('Invalid digest')
        if hashlib.sha256(data).hexdigest() != digest:
            raise ValueError('Digest mismatch')

    return {'files': len(entries), 'total_bytes': total_bytes}
"}
